import{_ as a,c as e,a2 as t,o as r}from"./chunks/framework.CqbvlPrP.js";const _=JSON.parse('{"title":"什么是趋势跟踪","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易技术/趋势交易/什么是趋势跟踪.md","filePath":"stock/交易技术/趋势交易/什么是趋势跟踪.md"}'),o={name:"stock/交易技术/趋势交易/什么是趋势跟踪.md"};function i(n,p,s,l,h,c){return r(),e("div",null,p[0]||(p[0]=[t('<h1 id="什么是趋势跟踪" tabindex="-1">什么是趋势跟踪 <a class="header-anchor" href="#什么是趋势跟踪" aria-label="Permalink to &quot;什么是趋势跟踪&quot;">​</a></h1><h2 id="_01、趋势跟踪" tabindex="-1">01、趋势跟踪 <a class="header-anchor" href="#_01、趋势跟踪" aria-label="Permalink to &quot;01、趋势跟踪&quot;">​</a></h2><p>首先，这个问题探讨的是趋势跟踪。那么我们就需要明白，什么是趋势跟踪。</p><p>请注意，趋势跟踪是一种理念，不是一种方法。</p><p>趋势，指的是获利依靠趋势，跟踪，指的是走势为王，放弃自我臆测。</p><p>结合到一起，趋势跟踪的意思就是：</p><p>在走势为王的基础上，用相对较小的风险，去换取一波相对较大的收益。</p><p>趋势跟踪不是方法，是理念，是处理风险的逻辑。形容的是交易领域中，实现“以相对较小可控的风险尝试获取收益”的交易思路。</p><p>至于你如何去趋势跟踪，你如何具体实现的这个思路，是你自己的具体方法。用各位喜欢的词来说：</p><p>趋势跟踪是道，而趋势跟踪交易员的交易系统，是术。</p><p>所以，理论上而言，这个趋势跟踪这种交易方法已经落后的标题是有问题的，实际上，应该是，趋势跟踪这种理念是不是已经落后了？</p><p>而题主之所以觉得它落后了，是因为他接触到了一个新词。</p><h2 id="_02、结构" tabindex="-1">02、结构 <a class="header-anchor" href="#_02、结构" aria-label="Permalink to &quot;02、结构&quot;">​</a></h2><p>在题主略带自信的问题描述中，讲了一个结构概念，并且立即将这个词进行了主观层面的升华。</p><p>为什么会这样？</p><p>之所以一个“结构概念”能击中题主的兴奋点，是因为他在趋势交易的过程中，一直搞不懂一个问题，这个问题就是：</p><p>“如何区分震荡和趋势？”</p><p>“什么是震荡，什么又TM的是趋势呢？”</p><p>他定义不准，他也不知道如何定义，所以，当有人说：市场是分结构的！他就会兴奋，他觉得对方说得太对了，只有在震荡行情中做震荡，趋势行情中做趋势才是无敌的嘛。</p><p>什么趋势跟踪根本就划分不了这两者，怎么可能赚钱？</p><p>趋势中是能够获利，但是震荡中岂不是就亏回去了？无法区分震荡和趋势，还玩趋势跟踪？看来，这种方法太古老了，被人吹过头了。</p><p>只有区分出市场结构的交易方法才是真正无敌的！</p><p>所以，题主的逻辑很清晰，但是认知有限，因为他不知道一件事情。</p><h2 id="_03、趋势与震荡" tabindex="-1">03、趋势与震荡 <a class="header-anchor" href="#_03、趋势与震荡" aria-label="Permalink to &quot;03、趋势与震荡&quot;">​</a></h2><p>趋势跟踪领域的中高水准的交易者都知道如何区分震荡和趋势。</p><p>如何区分？</p><p>用自己的实现趋势跟踪交易理念的交易方法来区分。</p><p>趋势是一个主观性的名词，就跟上涨一样，没有标准。 每一个人都需要有能力定义出自己的趋势和震荡。</p><p>我的交易系统中，让我止损的走势都是震荡，让我获利的走势都是趋势。或者我的交易系统中，让我获利少于2个ATR的走势都是震荡，盈利超过了2个ATR的算小趋势，盈利超过了5个ATR的算大趋势。</p><p>实际上，一个合格的趋势跟踪交易员，拥有自己的交易系统的入门标志就是：拥有自己的交易系统并且开始一致性的执行。</p><p>交易系统是什么？是处理K线的一套具体方法，是趋势跟踪的实现手段。这个交易系统能够实现交易员的全部交易理念，而它具备的一个小小的功能，就是定义市场走势。</p><p>它早就给市场划分出来了他自己专属的“震荡”和“趋势”。</p><p>请注意，划分与不划分这些仅是表象，深层次的根本是信仰。他们不旦用自己的规则划分了震荡和趋势，而且他们还敢执行这套规则，这套系统。</p><p>你猜为啥？因为他们知道：</p><p>这样做有正预期，是对的，能赚钱。</p><p>有的人不知道，有的人不懂，有的人不信，而他们信，并且付出了行动。这就是认知的巨大区别。</p><p>当然了，当一个趋势跟踪的交易者交易了很长时间之后，他可能也懒得定义什么趋势和震荡。</p><p>他可能会说：</p><p>我管它什么震荡与趋势干嘛？走势是不确定的，一万个人眼中有一万种的趋势和震荡组合，这玩意有啥互相探讨的必要？我为什么非要清晰的定义出趋势和震荡来跟你探讨个123呢？我的交易方法有正预期，我累积的获利足够覆盖掉我付出的风险，我能在控制住风险的基础上获取收益不就可以了？</p><h2 id="_04、认知突破" tabindex="-1">04、认知突破 <a class="header-anchor" href="#_04、认知突破" aria-label="Permalink to &quot;04、认知突破&quot;">​</a></h2><p>题主的认知突破点在于深刻的理解走势的不确定性和不确定性背后的盈利的根本来源。</p><p>趋势跟踪的专业玩家眼中，市场走势是不确定的，我们没有办法清晰的定义出趋势和震荡，我们自然也就没有办法在趋势中梭哈趋势，在震荡中梭哈震荡。</p><p>请注意，他们都知道这样做很爽。</p><p>看准了一把梭是所有人的梦想，可关键在于：没有人能做到。</p><p>交易不是解密游戏，不是寻找当下走势是震荡还是趋势的“确定性游戏”，那都是新手的意淫和妄想而已。</p><p>走势是不确定的，谁也无法精准的清晰的像个先知一样清晰的定义出当下的走势到底是趋势还是震荡，那怎么办？</p><p>我用自己的规则定义。</p><p>我承担自己能够承担的风险，获取这风险背后的收益，同时，我不从偏执，我相信走势为王，我在错误的时候及时止损，我在正确的时候尝试获取更多的收益。</p><p>而且我知道，我这样做，能够获利。</p><p>在交易领域，这种风格被称为“趋势跟踪”。</p><p>在趋势跟踪的专业级玩家眼中：处理不确定性，唯我趋势跟踪。所以，投机之王杰西利弗莫尔说：投机如山岳一样古老，华尔街没有新鲜事。</p><p>海龟交易法则的作者柯蒂斯费思说：每隔一段时间，就会有人跳出来说趋势跟踪的交易方法已经走向了末日，每当这个时候我总是一笑了之，因为我知道，这意味着市场离遍地是黄金的日子不远了。</p><p>投机的基本原理早已确定。我们要做的不是创新，而是理解并执行。</p>',53)]))}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
